import axiosConfig from "../axiosConfig"
export const apiCreateSample = async (data) => {
    try {
        const response = await axiosConfig.post('/api/sample/createsample', data);
        return response.data;
    } catch (error) {
        throw error.message;
    }
};

export const apiGetAllSamplesByUserId = async (user_id) => {
    try {
        const response = await axiosConfig.get('/api/sample/getallsamplesbyuserid', {
            params: { user_id }
        });
        return response.data;
    } catch (error) {
        throw error.message;
    }
};
